import json, glob, os

TARGET_SEGMENTS = {"full_story_part1", "full_story_part2", "point_one", "point_two"}
EXCLUDE_SUBSTR = ["er012_output", "_gate_tmp_"]

targets = {}
files = sorted(glob.glob("**/tts_generation_results.json", recursive=True))
for fp in files:
    fpn = fp.replace("\\", "/")
    if any(x in fpn for x in EXCLUDE_SUBSTR):
        continue
    try:
        d = json.load(open(fp, encoding="utf-8"))
    except Exception:
        continue
    segs = d.get("segments") if isinstance(d, dict) else None
    if not isinstance(segs, dict):
        continue
    for seg_name, rec in segs.items():
        if seg_name not in TARGET_SEGMENTS or not isinstance(rec, dict):
            continue
        attempts = rec.get("attempts_log") or []
        final_attempt = None
        for a in attempts:
            if a.get("verified"):
                final_attempt = a
        if final_attempt is None and attempts:
            final_attempt = attempts[-1]
        checked = bool(final_attempt.get("repetition_qa_checked")) if final_attempt else None
        if checked:
            continue
        wav_path = rec.get("path")
        text = rec.get("text")
        if not wav_path or not text or not os.path.exists(wav_path):
            continue
        wav_path_n = wav_path.replace("\\", "/")
        if wav_path_n not in targets:
            targets[wav_path_n] = {"wav_path": wav_path_n, "text": text, "sources": []}
        targets[wav_path_n]["sources"].append({"file": fpn, "segment": seg_name})

out = list(targets.values())
